const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const hasPublicationJobId = uuidRegex.test(publicationJobId);
const hasGenerationJobId = uuidRegex.test(generationJobId);
if (!hasPublicationJobId && !hasGenerationJobId) {
  return [{ json: { query: "SELECT false AS ok, 'publicationJobId or generationJobId is required' AS error;" } }];
