), selected_publication AS (
  SELECT pj.*
  FROM publication_jobs pj
  LEFT JOIN selected_generation sg ON true
  WHERE ${publicationConditions.length ? publicationConditions.join(' OR ') + ' OR ' : ''}(sg.job_id IS NOT NULL AND pj.publication_job_id::text = sg.request_payload->>'publicationJobId')
  ORDER BY pj.updated_at DESC
  LIMIT 1
)
SELECT
  CASE WHEN EXISTS (SELECT 1 FROM selected_generation) THEN true ELSE false END AS ok,
  CASE WHEN NOT EXISTS (SELECT 1 FROM selected_generation) THEN 'Generation job not found' ELSE NULL END AS error,
  (SELECT jsonb_build_object(
    'publicationJobId', publication_job_id,
    'avatar', avatar,
    'scene', scene,
    'format', format,
    'status', status,
    'metadata', metadata
  ) FROM selected_publication) AS job,
  (SELECT jsonb_build_object(
    'generationJobId', job_id,
    'status', status,
    'runMode', run_mode,
    'requestPayload', request_payload,
    'resultPayload', result_payload,
    'providerPromptId', COALESCE(result_payload->>'providerPromptId', result_payload->'providerResponse'->>'prompt_id', result_payload->'gateway'->'response'->>'prompt_id'),
