  publication_job_id uuid NOT NULL REFERENCES publication_jobs(publication_job_id) ON DELETE CASCADE,
  event_type text NOT NULL,
  event_payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
WITH updated_generation AS (
  UPDATE generation_jobs
  SET
    status = ${sql(generationStatus)},
    result_payload = COALESCE(result_payload, '{}'::jsonb) || ${sqlJson(statusPayload)},
    error_message = ${sql(errorMessage)},
    completed_at = CASE WHEN ${completed ? 'true' : 'false'} THEN COALESCE(completed_at, now()) ELSE completed_at END,
    failed_at = CASE WHEN ${failed ? 'true' : 'false'} THEN COALESCE(failed_at, now()) ELSE failed_at END,
