      'generationProviderStatus', ${sql(providerStatus)},
      'generationProviderPromptId', ${sql(statusPayload.providerPromptId)},
      'generationProviderOutputs', ${sqlJson(outputs)},
      'generationLastCheckedAt', now()
    )
  WHERE pj.publication_job_id = ${sql(job.publicationJobId)}::uuid
  RETURNING *
), event AS (
  INSERT INTO publication_job_events (publication_job_id, event_type, event_payload)
  VALUES (${sql(job.publicationJobId)}::uuid, ${sql(eventType)}, ${sqlJson(statusPayload)})
  RETURNING *
)
SELECT
  ${failed ? 'false' : 'true'} AS ok,
  ${sql(errorMessage)} AS error,
  (SELECT row_to_json(updated_publication) FROM updated_publication) AS job,
  (SELECT jsonb_build_object(
    'generationJobId', job_id,
    'status', status,
    'provider', 'comfy-cloud',
    'providerPromptId', result_payload->>'providerPromptId',
    'providerStatus', result_payload->>'providerStatus',
    'providerOutputs', result_payload->'providerOutputs',
    'completedAt', completed_at,
    'failedAt', failed_at
  ) FROM updated_generation) AS generation,
  ${sqlJson(statusPayload)} AS provider;
`;
